@@ -1,0 +1,75 @@
+const quizForm = document.querySelector("#quiz-form");
+const result = document.querySelector("#quiz-result");
+
+const correctAnswers = {
+  "question-1": ["python", "javascript"],
+  "question-2": ["javascript", "php", "ruby"],
+  "question-3": ["java", "typescript", "csharp"],
+};
+
+function getSelectedAnswers(questionName) {
+  return Array.from(
+    quizForm.querySelectorAll(`input[name="${questionName}"]:checked`),
+    (input) => input.value,
+  );
+}
+
+function answerSetsMatch(selectedAnswers, acceptedAnswers) {
+  return (
+    selectedAnswers.length === acceptedAnswers.length &&
+    selectedAnswers.every((answer) => acceptedAnswers.includes(answer))
+  );
+}
+
+function setQuestionError(questionName, hasError) {
+  const inputs = quizForm.querySelectorAll(`input[name="${questionName}"]`);
+  const error = document.querySelector(`#${questionName}-error`);
+
+  inputs.forEach((input) => {
+    input.setAttribute("aria-invalid", String(hasError));
+  });
+
+  error.hidden = !hasError;
+}
+
+quizForm.addEventListener("change", (event) => {
+  const questionName = event.target.name;
+
+  if (questionName && correctAnswers[questionName]) {
+    setQuestionError(questionName, getSelectedAnswers(questionName).length === 0);
+  }
+});
+
+quizForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const questionNames = Object.keys(correctAnswers);
+  let firstInvalidInput = null;
+
+  questionNames.forEach((questionName) => {
+    const hasError = getSelectedAnswers(questionName).length === 0;
+    setQuestionError(questionName, hasError);
+
+    if (hasError && !firstInvalidInput) {
+      firstInvalidInput = quizForm.querySelector(`input[name="${questionName}"]`);
+    }
+  });
+
+  if (firstInvalidInput) {
+    result.hidden = true;
+    result.textContent = "";
+    firstInvalidInput.focus();
+    return;
+  }
+
+  const score = questionNames.reduce((total, questionName) => {
+    const selectedAnswers = getSelectedAnswers(questionName);
+    const acceptedAnswers = correctAnswers[questionName];
+    return total + (answerSetsMatch(selectedAnswers, acceptedAnswers) ? 1 : 0);
+  }, 0);
+
+  result.hidden = false;
+  result.textContent = `You scored ${score} out of ${questionNames.length}.`;
+  result.scrollIntoView({ behavior: "smooth", block: "nearest" });
+});
+

')
